const $=s=>document.querySelector(s);const safe=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
$('#tocToggle').onclick=()=>{const open=$('#toc').hidden;$('#toc').hidden=!open;$('#tocToggle').setAttribute('aria-expanded',open)};document.querySelectorAll('#toc a').forEach(a=>a.onclick=()=>{$('#toc').hidden=true;$('#tocToggle').setAttribute('aria-expanded','false')});document.addEventListener('keydown',e=>{if(e.key==='Escape'){$('#toc').hidden=true;$('#tocToggle').setAttribute('aria-expanded','false')}});
let storage={get(k){try{return localStorage.getItem(k)}catch{return null}},set(k,v){try{localStorage.setItem(k,v)}catch{}}};if(storage.get('gt-theme')==='dark')document.body.classList.add('dark');$('#theme').onclick=()=>{document.body.classList.toggle('dark');storage.set('gt-theme',document.body.classList.contains('dark')?'dark':'light')};
addEventListener('scroll',()=>{let n=document.documentElement.scrollHeight-innerHeight;$('#progress').style.width=(n>0?scrollY/n*100:0)+'%'},{passive:true});
const cards=[['三份文献各有什么任务？','海德堡：教理与安慰；比利时：公共告白；多特：恩典争议的辨明。'],['海德堡的三段主线？','罪苦（主日2—4）→ 拯救（5—31）→ 感恩（32—52）；主日1以唯一安慰总领。'],['称义与成圣如何区分？','称义是神凭基督的义接纳罪人；成圣是圣灵真实更新人。根基不可混淆，恩惠不可割裂。'],['多特为何是五项、四个部分？','第三项人的败坏与第四项归正方式合并为III/IV；其余是I拣选、II赎罪、V保守。'],['圣约记号是否自动使人得救？','不是。记号印证神的应许，呼召信心与悔改；受洗身份不等于可以判定已重生。'],['拣选为何不会取消宣教？','神既定目标，也使用途径；向万人传福音是显明命令，不能以隐秘旨意筛选听者。'],['整本圣经的故事怎样记？','创造 → 堕落 → 应许与救赎 → 新创造；父差子，子成全，灵施行，招聚百姓与神同住。'],['真正的确据从哪里来？','根基是神在基督里的应许；圣灵作见证，信心与悔改的果子印证。感觉可能起伏，基督不改变。'],['圣餐为何不只是回忆？','圣灵使信徒凭信心真实领受基督的恩惠；饼酒仍是饼酒，十架献祭不再重复。'],['比利时信条的结构？','1—11神与启示；12—17创造、堕落与应许；18—26基督与救恩；27—36教会与公共生活；37末日。'],['历史记忆三组坐标？','1561南尼德兰：逼迫中的告白。1563海德堡：学校与讲台。1618—1619多特：争议中的辨明。'],['三一神要避免哪两个极端？','不能把三位混成同一位格的面具，也不能把一神分成三位神；一位神，三个位格。']];let ci=0;function card(){ $('#cardCount').textContent=`${ci+1} / ${cards.length}`;$('#cardQ').textContent=cards[ci][0];$('#cardA').textContent=cards[ci][1];$('#cardA').hidden=true;$('#reveal').textContent='显示答案'}card();$('#reveal').onclick=()=>{$('#cardA').hidden=!$('#cardA').hidden;$('#reveal').textContent=$('#cardA').hidden?'显示答案':'遮住答案'};$('#nextCard').onclick=()=>{if('speechSynthesis'in window)speechSynthesis.cancel();ci=(ci+1)%cards.length;card()};$('#speak').onclick=()=>{if(!('speechSynthesis'in window)){$('#cardA').hidden=false;return}if(speechSynthesis.speaking){speechSynthesis.cancel();return}let u=new SpeechSynthesisUtterance(cards[ci].join('。'));u.lang='zh-CN';u.rate=.88;speechSynthesis.speak(u)};$('#learned').checked=storage.get('gt-learned')==='yes';$('#learned').onchange=()=>{storage.set('gt-learned',$('#learned').checked?'yes':'no');$('#saved').textContent='已在本设备保存；不会上传学习记录。'};
function detail(n,title,text,ref,extra=''){return `<details class="entry"><summary><span class="num">${safe(n)}</span><b>${safe(title)}</b><small>${safe(extra)}</small></summary><div class="detail"><p>${safe(text)}</p><p class="ref">经文研读：${safe(ref)}</p></div></details>`}
fetch('study.json').then(r=>{if(!r.ok)throw Error(r.status);return r.json()}).then(d=>{let h='';d.hc.forEach((r,i)=>{if([0,1,4,31].includes(i))h+=`<h3 class="subhead">${({0:'导论 · 唯一安慰',1:'第一部分 · 罪与愁苦',4:'第二部分 · 在基督里得拯救',31:'第三部分 · 感恩的生活'})[i]}</h3>`;h+=detail(`主日 ${r.day}`,r.title,r.text,r.ref,`问答 ${r.range}`)});$('#hcContent').innerHTML=h;$('#bcContent').innerHTML=d.bc.map(r=>detail(`第 ${r.article} 条`,r.title,r.text,r.ref)).join('');$('#dortContent').innerHTML=d.dort.map(r=>`<article class="dort-head"><span class="pill rose">${safe(r.key)}</span><h3>${safe(r.title)}</h3><p>${safe(r.intro)}</p><p class="ref">经文研读：${safe(r.ref)}</p><div class="article-list">${r.items.split('|').map((v,i)=>`<div class="entry"><b>${safe(r.key)}.${i+1}</b>${safe(v)}</div>`).join('')}</div><details class="errors entry"><summary><b>对应驳误 · ${r.errors.split('|').length}条提要</b></summary><ol>${r.errors.split('|').map(v=>`<li>${safe(v)}</li>`).join('')}</ol><p class="ref">以上是对所反对命题的编辑概括，不能替代驳误原文的完整限定与论证。</p></details><div class="callout"><b>牧养应用</b><br>${safe(r.apply)}</div></article>`).join('');let entries=[...document.querySelectorAll('.entry')];$('#search').oninput=e=>{let q=e.target.value.trim().toLowerCase(),count=0;entries.forEach(x=>{let match=!q||x.textContent.toLowerCase().includes(q);x.hidden=!match;if(match)count++;if(q&&match&&x.tagName==='DETAILS')x.open=true});$('#results').textContent=q?`找到 ${count} 个匹配条目（含多特驳误组）；清空搜索可显示全部。`:''};$('#expand').onclick=()=>document.querySelectorAll('.library details').forEach(x=>x.open=true);$('#collapse').onclick=()=>document.querySelectorAll('.library details').forEach(x=>x.open=false)}).catch(()=>{$('#hcContent').textContent='导读数据未能加载。请通过网站链接访问，或用本地预览服务打开，避免直接双击HTML。'});
addEventListener('beforeprint',()=>{document.querySelectorAll('details').forEach(d=>{d.dataset.wasOpen=String(d.open);d.open=true})});addEventListener('afterprint',()=>{document.querySelectorAll('details').forEach(d=>d.open=d.dataset.wasOpen==='true')});
